<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import RecordAudit from './RecordAudit.vue'
import { api, beijingTime, queryParams, type Page } from './api'
import { errorMessage, statusLabel, servers, type Server } from './monitoring'
interface Job {id:string;owner:string;kind:string;created:number;updated:number;status:string;processed:number;skipped:number;message:string}
interface Preview {id:string;expires:number;counts:{eligible:number;protected:number}}
interface Status {retention:Record<string,number>;items:{category:string;count:number;oldest:number}[];files:{name:string;bytes:number|null;wal_bytes:number|null}[];automatic:Page<Job>}
const route=useRoute(),data=ref<Status>(),nodes=ref<Server[]>([]),jobs=ref<Job[]>([]),total=ref(0),page=ref(1),error=ref(''),busy=ref(false),preview=ref<Preview>(),exportJob=ref<Job>(),exportFirst=ref(false),confirm=ref(false)
const category=ref(String(route.query.category||'all')),node=ref(String(route.query.node||'')),before=ref(new Date(Date.now()-30*86400000)),now=ref(Date.now()/1000)
const categories:Record<string,string>={all:'全部可清理历史',events:'普通文件与运行事件',security:'安全扫描命中',website:'网站故障历史',server:'服务器告警历史',notifications:'通知历史'}
let disposed=false,generation=0,previewGeneration=0,timer:ReturnType<typeof setInterval>|undefined,polling=false
const bytes=(n:number|null)=>n===null?'未知':`${(n/1048576).toFixed(2)} MiB`
function invalidate(){previewGeneration++;preview.value=undefined;exportJob.value=undefined;confirm.value=false}
watch([category,node,before],invalidate)
async function load(){const current=++generation;try{const results=await Promise.all([api<Status>('/api/retention/status'),api<Page<Job>>('/api/retention/jobs?'+queryParams({page:page.value,page_size:20})),servers()]);if(disposed||current!==generation)return;data.value=results[0];jobs.value=results[1].items;total.value=results[1].total;nodes.value=results[2].items;error.value=''}catch(e){if(!disposed&&current===generation)error.value=errorMessage(e)}}
async function inspect(){const current=++previewGeneration;busy.value=true;error.value='';try{const result=await api<Preview>('/api/retention/preview','POST',{category:category.value,node:node.value,before:Math.floor(before.value.getTime()/1000)});if(disposed||current!==previewGeneration)return;preview.value=result;exportJob.value=undefined}catch(e){if(!disposed&&current===previewGeneration)error.value=errorMessage(e)}finally{busy.value=false}}
async function start(kind:'export'|'cleanup'){if(!preview.value)return;busy.value=true;error.value='';try{const job=await api<Job>(`/api/retention/${kind}`,'POST',{preview:preview.value.id,confirm:kind==='cleanup',export_job:kind==='cleanup'&&exportFirst.value?exportJob.value?.id:''});if(kind==='export')exportJob.value=job;else{confirm.value=false;preview.value=undefined};await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function poll(){now.value=Date.now()/1000;if(disposed||document.hidden||polling)return;if(!jobs.value.some(j=>['pending','running'].includes(j.status))&&!exportJob.value)return;polling=true;try{if(exportJob.value){const job=await api<Job>(`/api/retention/jobs/${exportJob.value.id}`);if(!disposed)exportJob.value=job};await load()}catch(e){if(!disposed)error.value=errorMessage(e)}finally{polling=false}}
onMounted(()=>{void load();timer=setInterval(poll,5000)})
onUnmounted(()=>{disposed=true;generation++;clearInterval(timer)})
</script>
<template><el-card class="retention-panel" shadow="never"><div class="card-heading"><h3>存储与清理</h3><el-button :loading="busy" @click="load">刷新统计</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><p class="muted">这里显示实际已应用的期限；修改上方 YAML 设置后，需保存并应用。删除记录后 SQLite 空间可复用，数据库文件未必立即缩小。</p><div v-if="data" class="storage-files"><p v-for="f in data.files" :key="f.name">{{f.name}}：{{bytes(f.bytes)}}；WAL：{{bytes(f.wal_bytes)}}</p></div><el-table v-if="data" :data="data.items"><el-table-column label="历史类别"><template #default="{row}">{{categories[row.category]}}</template></el-table-column><el-table-column prop="count" label="记录数量"/><el-table-column label="最早时间"><template #default="{row}">{{row.oldest?beijingTime(row.oldest):'—'}}</template></el-table-column></el-table><p v-if="data" class="muted">实际期限：普通事件 {{data.retention.sqlite_events_days}} 天；安全命中 {{data.retention.security_events_days}} 天；网站故障 {{data.retention.website_incidents_days}} 天；服务器告警 {{data.retention.server_alerts_days}} 天；通知 {{data.retention.delivery_records_days}} 天。</p><p v-if="data?.automatic.items[0]">最近自动清理：{{beijingTime(data.automatic.items[0].updated)}} · {{statusLabel(data.automatic.items[0].status)}} · 已删除 {{data.automatic.items[0].processed}} 条 · 跳过 {{data.automatic.items[0].skipped}} 条 <span v-if="data.automatic.items[0].message">{{data.automatic.items[0].message}}</span></p>
<h4>手动清理预览</h4><div class="filters"><el-select v-model="category"><el-option v-for="[key,label] in Object.entries(categories)" :key="key" :value="key" :label="label"/></el-select><el-select v-model="node" clearable :value-on-clear="''" placeholder="全部服务器"><el-option v-for="n in nodes" :key="n.id" :value="n.id" :label="n.name"/></el-select><el-date-picker v-model="before" type="datetime" placeholder="截止日期" :clearable="false"/><el-button :loading="busy" @click="inspect">预览范围</el-button></div><p class="muted">仅清理截止时间之前的历史；最近 24 小时、当前异常、未结束故障及待投递记录受保护。指标和备份按各自策略管理，清理不撤销已经发送的消息，也不代表风险已解决。</p>
<div v-if="preview"><el-alert :title="`可清理 ${preview.counts.eligible} 条，受保护 ${preview.counts.protected} 条；预览有效期 10 分钟。`" type="warning" :closable="false"/><p><el-checkbox v-model="exportFirst">先导出本次范围，导出成功后再清理</el-checkbox></p><el-button :loading="busy" :disabled="now>=preview.expires" @click="start('export')">导出 JSONL</el-button><a v-if="exportJob?.status==='complete'" :href="`/api/retention/jobs/${exportJob.id}/download`">下载导出文件</a><span v-if="exportJob"> 导出：{{statusLabel(exportJob.status)}} {{exportJob.message}}</span><el-button type="danger" :disabled="busy||now>=preview.expires||exportFirst&&exportJob?.status!=='complete'" @click="confirm=true">清理本次范围</el-button><p v-if="now>=preview.expires">预览已过期，请重新预览。</p></div>
<h4>清理与导出历史</h4><el-table :data="jobs" empty-text="尚无手动任务"><el-table-column label="时间" min-width="180"><template #default="{row}">{{beijingTime(row.created)}}</template></el-table-column><el-table-column label="操作"><template #default="{row}">{{row.kind==='export'?'导出':'清理'}} · {{row.owner}}</template></el-table-column><el-table-column label="结果"><template #default="{row}">{{statusLabel(row.status)}}；完成 {{row.processed}} 条，跳过 {{row.skipped}} 条</template></el-table-column><el-table-column prop="message" label="原因"/><el-table-column label="下载"><template #default="{row}"><a v-if="row.kind==='export'&&row.status==='complete'&&now-row.updated<86400" :href="`/api/retention/jobs/${row.id}/download`">下载 JSONL</a></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @change="load"/><p class="muted">导出文件保存 24 小时；清理审计保留 365 天。历史删除后无法通过调大期限恢复。</p></el-card>
<el-dialog v-model="confirm" title="确认清理历史" width="min(520px,96vw)"><p>将删除本次预览中符合条件且未受保护的历史记录。此操作不能撤销，已删除数据需通过备份或导出留档。</p><p v-if="!exportFirst">本次未要求先导出，请确认已完成必要留档。</p><template #footer><el-button @click="confirm=false">取消</el-button><el-button type="danger" :loading="busy" @click="start('cleanup')">确认清理</el-button></template></el-dialog>
<RecordAudit/></template>
